begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','39090000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('39090000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','reimbursement-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,6) i;
select pg_temp.login(1);
create temp table ctx as select public.create_project('Acknowledgements fixture','UTC','GBP','2026-01-01') id;
create temp table cat as with c as(insert into public.project_areas(project_id,title) select id,'Villa' from ctx returning id) select * from c;
set local role postgres;
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.id,('39090000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Reimbursement member '||i,case when i=4 then 'viewer' else 'member' end::public.member_role,'active' from ctx,generate_series(2,4) i;
create temp table members as select right(user_id::text,1)::int n,id from public.project_members where project_id=(select id from ctx);
grant select on members to authenticated;
select pg_temp.login(1);
create temp table activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Villa","kind":"other","activity_type":"task","estimated_cost_minor":90000}',null)).id;
select public.set_activity_cost_split((select id from activity),jsonb_build_object('mode','even','cost',90000,'members',(select jsonb_agg(id order by id) from members where n<=3)));
create temp table payment as with p as(insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,activity.id,members.id,'full','outgoing','paid',90000,current_date from ctx,activity,members where n=1 returning id) select * from p;
insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select ctx.id,activity.id,'Vendor schedule',90000,current_date+30 from ctx,activity;
create temp table before_schedules as select jsonb_agg(to_jsonb(s) order by payment_schedule_id) doc from public.v_activity_payment_schedule_financials s where project_id=(select id from ctx);
create temp table before_financial as select to_jsonb(f) doc from public.v_project_financials f where project_id=(select id from ctx);
create temp table before_balances as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.v_activity_member_settlements s where commitment_id=(select id from activity);
create temp table before_member_balances as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.v_member_balances s where project_id=(select id from ctx);
create temp table before_shares as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.cost_shares s where commitment_id=(select id from activity);
create temp table request_a as select public.create_reimbursement((select id from payment),(select id from members where n=2),30000) id;
create temp table request_b as select public.create_reimbursement((select id from payment),(select id from members where n=3),30000) id;
create function pg_temp.financial_snapshot() returns jsonb language sql as $$
 select jsonb_build_object('project',(select jsonb_agg(to_jsonb(t)) from public.v_project_financials t where project_id=(select id from ctx)),
 'activity',(select jsonb_agg(to_jsonb(t) order by member_id) from public.v_activity_member_settlements t where project_id=(select id from ctx)),
 'members',(select jsonb_agg(to_jsonb(t) order by member_id) from public.v_member_balances t where project_id=(select id from ctx)),
 'schedules',(select jsonb_agg(to_jsonb(t) order by payment_schedule_id) from public.v_activity_payment_schedule_financials t where project_id=(select id from ctx)),
 'payments',(select jsonb_agg(to_jsonb(t) order by id) from public.payments t where project_id=(select id from ctx)),
 'shares',(select jsonb_agg(to_jsonb(t) order by member_id) from public.cost_shares t where project_id=(select id from ctx)),
 'requests',(select jsonb_agg(to_jsonb(t) order by id) from public.reimbursement_requests t where project_id=(select id from ctx)));
$$;
create temp table baseline as select pg_temp.financial_snapshot() doc;
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from request_a))$$,'42501',null,'Creditor organizer cannot impersonate debtor');
select pg_temp.login(3);
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from request_a))$$,'42501',null,'Unrelated member denied');
select is((select count(*)::int from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from request_a)),0,'Unrelated member cannot read status');
select pg_temp.login(4);
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from request_a))$$,'42501',null,'Unrelated Viewer denied');
select pg_temp.login(5);
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from request_a))$$,'42501',null,'Cross-project user denied');
select is((select count(*)::int from public.reimbursement_payment_acknowledgements),0,'Cross-project history invisible');
select pg_temp.login(2);
select throws_ok($$select public.acknowledge_reimbursement_payment('00000000-0000-0000-0000-000000000099')$$,'42501',null,'Nonexistent request denied');
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),0,'No payment link required');
select ok((select can_acknowledge from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from request_a)),'Eligible debtor sees explicit action');
create temp table ack as select public.acknowledge_reimbursement_payment((select id from request_a)) id;
select is(public.acknowledge_reimbursement_payment((select id from request_a)),(select id from ack),'Exact retry returns same acknowledgement');
select is((select count(*)::int from public.reimbursement_payment_acknowledgements where reimbursement_request_id=(select id from request_a)),1,'Exactly one acknowledgement');
select is((select created_by_user_id from public.reimbursement_payment_acknowledgements where id=(select id from ack)),auth.uid(),'Server-derived actor');
select ok((select acknowledged_at between transaction_timestamp() and clock_timestamp() from public.reimbursement_payment_acknowledgements where id=(select id from ack)),'Server-authoritative timestamp');
select ok((select can_withdraw and not can_acknowledge from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from request_a)),'Active state offers undo only');
select is((select count(*)::int from public.get_project_health((select id from ctx)) where code='reimbursement_outstanding'),0,'Debtor Health removed');
select is((select count(*)::int from public.v_my_reimbursement_notifications where reimbursement_id=(select id from request_a)),0,'Debtor payment prompt removed');
select is((select count(*)::int from public.v_my_payment_acknowledgement_notifications),0,'No debtor self notification');
select throws_ok($$update public.reimbursement_payment_acknowledgements set acknowledged_at=now() where id=(select id from ack)$$,'42501',null,'Direct update denied');
select throws_ok($$delete from public.reimbursement_payment_acknowledgements where id=(select id from ack)$$,'42501',null,'Direct hard delete denied');
select throws_ok($$insert into public.reimbursement_payment_acknowledgements(project_id,reimbursement_request_id,debtor_member_id,created_by_user_id) select ctx.id,request_a.id,members.id,auth.uid() from ctx,request_a,members where n=2$$,'42501',null,'Direct insert denied');
select throws_ok($$select public.get_reimbursement_payment_options_before_acknowledgements((select id from request_a))$$,'42501',null,'Old endpoint cannot bypass suppression');
select pg_temp.login(1);
select is(pg_temp.financial_snapshot(),(select doc from baseline),'Acknowledgement and retry preserve complete financial/request snapshot');
select is((select count(*)::int from public.get_project_health((select id from ctx)) where code='reimbursement_outstanding'),0,'No creditor attention without confirmation action');
select is((select count(*)::int from public.v_my_payment_acknowledgement_notifications),1,'Creditor receives one notification');
select throws_ok($$select public.withdraw_reimbursement_payment_acknowledgement((select id from ack))$$,'42501',null,'Creditor organizer cannot undo debtor claim');
create temp table link as select public.save_my_payment_link('monzo','https://monzo.me/phase9-test') id;
select pg_temp.login(2);
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),0,'Server suppresses configured payment link');
select lives_ok($$select public.withdraw_reimbursement_payment_acknowledgement((select id from ack))$$,'Debtor can undo');
select lives_ok($$select public.withdraw_reimbursement_payment_acknowledgement((select id from ack))$$,'Undo exact retry harmless');
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),1,'Payment link returns after undo');
select is((select count(*)::int from public.get_project_health((select id from ctx)) where code='reimbursement_outstanding'),1,'Debtor Health returns after undo');
select pg_temp.login(1);
select is(pg_temp.financial_snapshot(),(select doc from baseline),'Undo preserves complete financial/request snapshot');
select is((select count(*)::int from public.v_my_payment_acknowledgement_notifications),1,'Withdrawal replaces obsolete sent inbox item');
select is((select kind from public.v_my_payment_acknowledgement_notifications),'reimbursement_payment_acknowledgement_withdrawn','Creditor sees withdrawal');
select pg_temp.login(2);
create temp table ack2 as select public.acknowledge_reimbursement_payment((select id from request_a)) id;
select isnt((select id from ack2),(select id from ack),'Re-acknowledgement creates new identity');
select public.withdraw_reimbursement_payment_acknowledgement((select id from ack));
select is((select active_acknowledgement_id from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from request_a)),(select id from ack2),'Delayed old undo cannot withdraw newer claim');
select is((select jsonb_array_length(history) from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from request_a)),2,'Full history retained');
set local role postgres;
select is((select count(*)::int from public.audit_log where entity_id=(select id from ack) and entity_type='reimbursement_payment_acknowledgements'),2,'Create and withdrawal audited exactly once');
select ok((select bool_and(not (coalesce(before,'{}'::jsonb) || coalesce(after,'{}'::jsonb)) ?| array['payment_url','provider','amount_minor']) from public.audit_log where entity_id=(select id from ack)),'Audit contains no amount or provider metadata');
select is((select count(*)::int from app.domain_events where resource_id=(select id from ack)),2,'One acknowledgement fact and one undo fact');
select is((select count(*)::int from app.domain_events where resource_id=(select id from ack2)),1,'Re-acknowledgement new fact');
select is((select count(*)::int from app.domain_event_processing where event_id in(select id from app.domain_events where resource_id in(select id from ack union select id from ack2))),3,'Three processing receipts');
select is((select count(*)::int from app.automation_action_runs where event_id in(select id from app.domain_events where resource_id in(select id from ack union select id from ack2))),3,'Three action receipts');
select is((select count(*)::int from public.notifications where payment_acknowledgement_id in(select id from ack union select id from ack2)),3,'One creditor notification per transition');
select ok((select bool_and(payload=jsonb_build_object('activity_id',(select id from activity),'reimbursement_request_id',(select id from request_a))) from app.domain_events where resource_id in(select id from ack union select id from ack2)),'Minimal payload without financial or personal metadata');
select ok((select bool_and(recipient_user_id='39090000-0000-4000-8000-000000000001') from public.notifications where payment_acknowledgement_id is not null and project_id=(select id from ctx)),'Creditor only');
select throws_ok($$update public.reimbursement_payment_acknowledgements set acknowledged_at=acknowledged_at-interval '1 day' where id=(select id from ack2)$$,'P0001',null,'Timestamp immutable');
select throws_ok($$update public.reimbursement_payment_acknowledgements set reimbursement_request_id=(select id from request_b) where id=(select id from ack2)$$,'P0001',null,'Request immutable');
select throws_ok($$update public.reimbursement_payment_acknowledgements set debtor_member_id=(select id from members where n=3) where id=(select id from ack2)$$,'P0001',null,'Debtor immutable');
select throws_ok($$delete from public.reimbursement_payment_acknowledgements where id=(select id from ack2)$$,'P0001',null,'History cannot be deleted');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.reimbursement_payment_acknowledgements'::regclass),'RLS enabled and forced');
select pg_temp.login(1);
update public.project_members set role='viewer' where id=(select id from members where n=3);
select pg_temp.login(3);
create temp table viewer_ack as select public.acknowledge_reimbursement_payment((select id from request_b)) id;
select ok((select id from viewer_ack) is not null,'Viewer debtor allowed');
select lives_ok($$select public.withdraw_reimbursement_payment_acknowledgement((select id from viewer_ack))$$,'Viewer debtor can undo');
select pg_temp.login(1);
create temp table token as select public.regenerate_project_join_link((select id from ctx)) value;
select pg_temp.login(5);
select public.request_project_access((select value from token));
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from request_a))$$,'42501',null,'Pending requester denied');
select pg_temp.login(1);
update public.project_members set status='removed' where id=(select id from members where n=3);
select pg_temp.login(3);
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from request_b))$$,'42501',null,'Removed debtor denied');
select is((select count(*)::int from public.v_reimbursement_payment_status),0,'Removed member loses history access');
select pg_temp.login(1);
update public.project_members set status='active' where id=(select id from members where n=3);
update public.projects set status='archived' where id=(select id from ctx);
select pg_temp.login(2);
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from request_a))$$,'42501',null,'Archived acknowledge denied');
select throws_ok($$select public.withdraw_reimbursement_payment_acknowledgement((select id from ack2))$$,'42501',null,'Archived undo denied');
select is((select jsonb_array_length(history) from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from request_a)),2,'Archived history readable');
select pg_temp.login(1);
update public.projects set status='active' where id=(select id from ctx);
select is(pg_temp.financial_snapshot(),(select doc from baseline),'Re-acknowledgement and Viewer transitions preserve finances');
insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on)
select ctx.id,activity.id,members.id,'refund','incoming','paid',1000,current_date from ctx,activity,members,payment where n=1;
select pg_temp.login(2);
select ok((select needs_review from public.v_reimbursements where id=(select id from request_a)),'Refund causes Review needed');
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from request_a))$$,'42501',null,'Stale acknowledge denied');
select throws_ok($$select public.withdraw_reimbursement_payment_acknowledgement((select id from ack2))$$,'42501',null,'Stale undo denied');
select is((select jsonb_array_length(history) from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from request_a)),2,'Stale history preserved');
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from request_a))),0,'Stale links suppressed');
select pg_temp.login(1);
create temp table stale_finance as select pg_temp.financial_snapshot()-'requests' doc;
select lives_ok($$select public.cancel_reimbursement((select id from request_a))$$,'Cancellation remains allowed after sent');
select is(pg_temp.financial_snapshot()-'requests',(select doc from stale_finance),'Cancellation after sent creates no settlement');
select is((select count(*)::int from public.v_my_payment_acknowledgement_notifications where reimbursement_id=(select id from request_a)),0,'Cancelled notification hidden');
select pg_temp.login(2);
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from request_a))$$,'42501',null,'Cancelled acknowledge denied');
select throws_ok($$select public.withdraw_reimbursement_payment_acknowledgement((select id from ack2))$$,'42501',null,'Cancelled undo denied');
select is((select jsonb_array_length(history) from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from request_a)),2,'Cancellation preserves history');
-- Independent, pre-existing finance mutations can make an acknowledgement stale.
select pg_temp.login(1);
create temp table changed_activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Share change","kind":"other","activity_type":"task","estimated_cost_minor":90000}',null)).id;
select public.set_activity_cost_split((select id from changed_activity),jsonb_build_object('mode','even','cost',90000,'members',(select jsonb_agg(id order by id) from members where n<=3)));
create temp table changed_payment as with p as(insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,changed_activity.id,members.id,'full','outgoing','paid',90000,current_date from ctx,changed_activity,members where n=1 returning id) select * from p;
create temp table changed_request as select public.create_reimbursement((select id from changed_payment),(select id from members where n=2),30000) id;
select pg_temp.login(2);
create temp table changed_ack as select public.acknowledge_reimbursement_payment((select id from changed_request)) id;
select pg_temp.login(1);
select public.set_activity_cost_split((select id from changed_activity),jsonb_build_object('mode','custom','cost',90000,'members',(select jsonb_agg(id order by id) from members where n<=3),'amounts',(select jsonb_object_agg(id::text,case when n=1 then 20000 when n=2 then 40000 else 30000 end) from members where n<=3)));
select pg_temp.login(2);
select ok((select needs_review from public.v_reimbursements where id=(select id from changed_request)),'Share change after acknowledgement causes Review needed');
select is((select active_acknowledgement_id from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from changed_request)),(select id from changed_ack),'Share change preserves claim identity');
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from changed_request))$$,'42501',null,'Share-stale retry denied');
select pg_temp.login(1);
select public.cancel_reimbursement((select id from changed_request));
create temp table settlement_request as select public.create_reimbursement((select id from changed_payment),(select id from members where n=2),40000) id;
select pg_temp.login(2);
create temp table settlement_ack as select public.acknowledge_reimbursement_payment((select id from settlement_request)) id;
select pg_temp.login(1);
-- Test the established settlement API as an unrelated external basis change;
-- no acknowledgement function invokes it.
select public.record_item_settlement((select id from changed_activity),(select id from members where n=2),(select id from members where n=1),1000,current_date);
select pg_temp.login(2);
select ok((select needs_review from public.v_reimbursements where id=(select id from settlement_request)),'Independent existing settlement makes claim stale');
select is((select active_acknowledgement_id from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from settlement_request)),(select id from settlement_ack),'Settlement preserves claim history');
select throws_ok($$select public.withdraw_reimbursement_payment_acknowledgement((select id from settlement_ack))$$,'42501',null,'Settlement-stale undo denied');
select is((select count(*)::int from public.get_reimbursement_payment_options((select id from settlement_request))),0,'Settlement-stale links absent');
select pg_temp.login(1);
select public.soft_delete_commitment((select id from changed_activity));

set local role anon;
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from request_a))$$,'42501',null,'Anonymous mutation denied');
select throws_ok($$select * from public.reimbursement_payment_acknowledgements$$,'42501',null,'Anonymous history denied');
set local role postgres;
update public.commitments set deleted_at=now() where id=(select id from activity);
select pg_temp.login(2);
select is((select count(*)::int from public.v_reimbursement_payment_status),0,'Deleted Activity hides history');
select throws_ok($$select public.acknowledge_reimbursement_payment((select id from request_a))$$,'42501',null,'Deleted Activity denied');
set local role postgres;
update public.commitments set deleted_at=null where id=(select id from activity);
select pg_temp.login(1);
select public.soft_delete_project((select id from ctx));
select pg_temp.login(2);
select is((select count(*)::int from public.v_reimbursement_payment_status),0,'Deleted project hides history');
select throws_ok($$select public.withdraw_reimbursement_payment_acknowledgement((select id from ack2))$$,'42501',null,'Deleted project denied');
set local role postgres;
select is((select count(*)::int from public.reimbursement_payment_acknowledgements where project_id=(select id from ctx)),5,'Soft deletion privately retains history');
select * from finish();
rollback;
